// Initialize monitoring session
const monitoringSession = {
  sessionId: 'monitor_' + Date.now(),
  startTime: new Date().toISOString(),
  monitoringType: 'continuous',
  systemHealth: {
    status: 'unknown',
    checks: [],
    metrics: {}
  },
  testResults: {
    recent: [],
    trends: {},
    alerts: []
  },
  performanceData: {
    current: {},
    historical: [],
    baselines: {}
  },
  alerts: {
    active: [],
    resolved: [],
    escalated: []
  }
};

return [{
  json: {
    ...monitoringSession,
    status: 'monitoring_started',
    currentPhase: 'health_checks'
  }
}];

// Analyze monitoring data and detect anomalies
const healthData = $input.item(0).json;
const performanceData = $input.item(1).json;
const testData = $input.item(2).json;

const anomalyDetection = {
  session_id: healthData.sessionId,
  analysis_timestamp: new Date().toISOString(),
  anomalies: [],
  trends: {},
  alerts: [],
  system_status: 'healthy'
};

// Analyze health check results
if (healthData.healthChecks) {
  healthData.healthChecks.forEach(check => {
    if (check.status === 'failed' || check.status === 'warning') {
      anomalyDetection.anomalies.push({
        type: 'health_check_failure',
        component: check.component,
        severity: check.status === 'failed' ? 'high' : 'medium',
        details: check.details,
        timestamp: check.timestamp
      });
    }
  });
}

// Analyze performance metrics for anomalies
if (performanceData.metrics) {
  Object.keys(performanceData.metrics).forEach(metric => {
    const currentValue = performanceData.metrics[metric].current;
    const baseline = performanceData.metrics[metric].baseline;
    const threshold = performanceData.metrics[metric].threshold;

    if (baseline && threshold) {
      const percentChange = ((currentValue - baseline) / baseline) * 100;

      if (Math.abs(percentChange) > threshold) {
        anomalyDetection.anomalies.push({
          type: 'performance_anomaly',
          metric: metric,
          current_value: currentValue,
          baseline_value: baseline,
          percent_change: percentChange,
          severity: Math.abs(percentChange) > threshold * 2 ? 'high' : 'medium',
          timestamp: new Date().toISOString()
        });
      }

      // Detect trends
      if (performanceData.metrics[metric].trend) {
        anomalyDetection.trends[metric] = {
          direction: performanceData.metrics[metric].trend.direction,
          strength: performanceData.metrics[metric].trend.strength,
          duration: performanceData.metrics[metric].trend.duration
        };
      }
    }
  });
}

// Analyze test results for patterns
if (testData.recentResults) {
  const failedTests = testData.recentResults.filter(r => r.status === 'failed');
  const testSuites = {};

  failedTests.forEach(test => {
    if (!testSuites[test.suite]) {
      testSuites[test.suite] = { failed: 0, total: 0 };
    }
    testSuites[test.suite].failed++;
  });

  testData.recentResults.forEach(test => {
    if (!testSuites[test.suite]) {
      testSuites[test.suite] = { failed: 0, total: 0 };
    }
    testSuites[test.suite].total++;
  });

  // Identify test suites with high failure rates
  Object.keys(testSuites).forEach(suite => {
    const failureRate = (testSuites[suite].failed / testSuites[suite].total) * 100;
    if (failureRate > 20) {
      anomalyDetection.anomalies.push({
        type: 'test_failure_rate',
        suite: suite,
        failure_rate: failureRate,
        failed_tests: testSuites[suite].failed,
        total_tests: testSuites[suite].total,
        severity: failureRate > 50 ? 'high' : 'medium',
        timestamp: new Date().toISOString()
      });
    }
  });
}

// Determine overall system status
const highSeverityAnomalies = anomalyDetection.anomalies.filter(a => a.severity === 'high');
const mediumSeverityAnomalies = anomalyDetection.anomalies.filter(a => a.severity === 'medium');

if (highSeverityAnomalies.length > 0) {
  anomalyDetection.system_status = 'critical';
} else if (mediumSeverityAnomalies.length > 3) {
  anomalyDetection.system_status = 'warning';
} else if (mediumSeverityAnomalies.length > 0) {
  anomalyDetection.system_status = 'degraded';
}

return [{
  json: {
    ...anomalyDetection,
    health_summary: {
      total_anomalies: anomalyDetection.anomalies.length,
      high_severity: highSeverityAnomalies.length,
      medium_severity: mediumSeverityAnomalies.length,
      trends_detected: Object.keys(anomalyDetection.trends).length
    }
  }
}];

// Generate critical alerts for immediate notification
const criticalAnomalies = $json.anomalies.filter(a => a.severity === 'high');
const alerts = [];

criticalAnomalies.forEach(anomaly => {
  const alert = {
    alert_id: 'alert_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    severity: 'critical',
    type: anomaly.type,
    title: `Critical Alert: ${anomaly.type.replace(/_/g, ' ').toUpperCase()}`,
    message: this._generateAlertMessage(anomaly),
    component: anomaly.component || anomaly.metric || anomaly.suite,
    timestamp: anomaly.timestamp || new Date().toISOString(),
    session_id: $json.session_id,
    requires_immediate_action: true,
    escalation_level: 1
  };

  alerts.push(alert);
});

return alerts.map(alert => ({ json: alert }));

// Generate monitoring insights and recommendations
const insights = [];
const recommendations = [];

// Analyze system health trends
if ($json.trends && Object.keys($json.trends).length > 0) {
  Object.keys($json.trends).forEach(metric => {
    const trend = $json.trends[metric];
    if (trend.direction === 'increasing' && trend.strength > 0.7) {
      insights.push({
        type: 'concerning_trend',
        metric: metric,
        description: `${metric} is showing a strong increasing trend over ${trend.duration} periods`,
        impact: 'May indicate system stress or capacity issues'
      });

      recommendations.push({
        category: 'proactive_monitoring',
        priority: 'medium',
        metric: metric,
        action: 'Investigate cause of increasing trend and consider capacity planning'
      });
    }
  });
}

// Analyze anomaly patterns
const anomalyTypes = {};
$json.anomalies.forEach(anomaly => {
  if (!anomalyTypes[anomaly.type]) {
    anomalyTypes[anomaly.type] = 0;
  }
  anomalyTypes[anomaly.type]++;
});

Object.keys(anomalyTypes).forEach(type => {
  if (anomalyTypes[type] > 2) {
    insights.push({
      type: 'recurring_issue',
      issue_type: type,
      frequency: anomalyTypes[type],
      description: `Multiple instances of ${type.replace(/_/g, ' ')} detected`
    });

    recommendations.push({
      category: 'root_cause_analysis',
      priority: 'high',
      issue_type: type,
      action: `Investigate and address recurring ${type.replace(/_/g, ' ')} issues`
    });
  }
});

// Performance recommendations
const performanceData = $input.item(1).json.metrics;
if (performanceData.cpu_usage && performanceData.cpu_usage.current > 80) {
  recommendations.push({
    category: 'performance_optimization',
    priority: 'high',
    metric: 'cpu_usage',
    current_value: performanceData.cpu_usage.current,
    action: 'Monitor CPU usage closely and consider optimization or scaling'
  });
}

if (performanceData.memory_usage && performanceData.memory_usage.current > 85) {
  recommendations.push({
    category: 'performance_optimization',
    priority: 'high',
    metric: 'memory_usage',
    current_value: performanceData.memory_usage.current,
    action: 'Investigate memory usage patterns and optimize memory management'
  });
}

// Test result analysis
const testData = $input.item(2).json.recentResults;
const recentFailures = testData.filter(t => t.status === 'failed' && 
  (new Date() - new Date(t.timestamp)) < 3600000); // Last hour

if (recentFailures.length > 3) {
  insights.push({
    type: 'testing_concern',
    description: `${recentFailures.length} test failures in the last hour`,
    failed_suites: [...new Set(recentFailures.map(t => t.suite))]
  });

  recommendations.push({
    category: 'quality_assurance',
    priority: 'high',
    action: 'Investigate recent test failures and address underlying issues'
  });
}

return [{
  json: {
    sessionId: $json.session_id,
    insights,
    recommendations,
    summary: {
      total_insights: insights.length,
      total_recommendations: recommendations.length,
      high_priority_actions: recommendations.filter(r => r.priority === 'high').length,
      medium_priority_actions: recommendations.filter(r => r.priority === 'medium').length
    },
    timestamp: new Date().toISOString()
  }
}];
